contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient test balance");
        require(amount > 0, "amount must be positive");

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;
        uint contractBalanceBeforeWithdraw = address(c).balance;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint contractBalanceAfterWithdraw = address(c).balance;

        assert(
            amount <= contractBalanceBeforeWithdraw ||
            (reverted && contractBalanceAfterWithdraw == contractBalanceBeforeWithdraw)
        );
    }

    receive() external payable {}
}

